import{_ as p,l as s,o as r,c as i,v as a,p as l,x as o,d as n,i as c,S as b}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"kprobes 与 uprobes","description":"","frontmatter":{"title":"kprobes 与 uprobes","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kprobes-uprobes.md","filePath":"cs/kprobes-uprobes.md","lastUpdated":1789023840000}'),u={name:"cs/kprobes-uprobes.md"};function d(h,e,k,f,_,m){const t=s("Mermaid");return r(),i("div",null,[e[1]||(e[1]=a('<h1 id="kprobes-与-uprobes" tabindex="-1">kprobes 与 uprobes <a class="header-anchor" href="#kprobes-与-uprobes" aria-label="Permalink to &quot;kprobes 与 uprobes&quot;">​</a></h1><div class="epigraph"><p>kprobe 在内核指令处插入断点或跳转；uprobe 对用户 inode 的偏移做同样的事，无需重编目标。</p><footer>—— 据 Linux kprobes 文档；uprobe 说明；[ftrace](/cs/ftrace-tracepoints) 为静态点对照</footer></div><p><a href="/cs/ftrace-tracepoints">tracepoint</a> 要预先埋点。缺口是 <strong>动态探针</strong>：kprobe/uprobe，以及与调试器 INT3 的关系。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>kprobe：改指令为 int3/jmp，处理函数读寄存器。优化 kprobe 用跳转减断点税。uprobe：文件页写时拷贝打点，所有映射该文件的进程可见。缺口：与 <a href="/cs/kpti-os">KPTI</a>/CFI 的摩擦；并发修改指令。本课不写如何做恶意挂钩。</p><p><span class="marginnote">kretprobe 在返回处。对象是观测，不是热补丁全文——livepatch 后课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>注册地址 → 停机或用 text_poke 改代码 → 命中进处理。对照 <a href="/cs/syscall-trace">ptrace</a>：ptrace 停整个线程；probe 可只采样。对照 <a href="/cs/fuse">FUSE</a>：无关。对照 XDP：一个改包路径，一个改任意函数。</p>',8)),(r(),l(b,null,{default:o(()=>[c(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADDR%5B%22%E5%87%BD%E6%95%B0%E6%88%96%E5%81%8F%E7%A7%BB%22%5D%20--%3E%20BP%5B%22%E6%96%AD%E7%82%B9%2F%E8%B7%B3%E8%BD%AC%22%5D%0A%20%20BP%20--%3E%20HND%5B%22probe%20%E5%A4%84%E7%90%86%22%5D%0A%20%20HND%20--%3E%20RET%5B%22%E7%BB%A7%E7%BB%AD%E6%89%A7%E8%A1%8C%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>动态探针让未埋点的函数也可观测，是现场调试的核心。税与风险高于 tracepoint。不要写成病毒。与 <a href="/cs/kernel-hardening">hardening</a>：严格 CFI 下插入更难。</p><p>错误地址会 oops——要校验符号。</p><p>实现上：优化 kprobe 用跳转替代 int3，和 Ftrace 调用约定绑定。uprobe 在共享库上对所有进程生效，开销按进程数放大。指令替换必须停机或用 text_poke 同步。 读法上只引用<a href="/cs/ftrace-tracepoints">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「安全、启动与调试 / 观测与调试」课序里，对象是 <strong>kprobes 与 uprobes</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 arch 的指令替换。不保证 JIT 用户代码的 uprobe。下一课基于采样：perf。</p><p>版本字段会变，课序钉的是机制对象「kprobes 与 uprobes」，不是某一主线内核的结构体名。 后课默认：可在运行时对 k/u 指令打点。PMU 采样与 perf，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>kprobe 打内核，uprobe 打用户文件偏移。</li><li>比 tracepoint 灵活、更贵、更危险。</li><li>perf 采样是下一课。</li><li>出处：Linux kprobes/uprobes；ftrace。</li></ul>',11))])}const T=p(u,[["render",d]]);export{B as __pageData,T as default};
